package com.pvp.travelmatch.repository; import com.pvp.travelmatch.entity.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface PaymentTransactionRepository extends JpaRepository<PaymentTransaction,Long>{ Optional<PaymentTransaction> findByProviderOrderId(String id); Optional<PaymentTransaction> findByProviderPaymentId(String id); Page<PaymentTransaction> findAllByOrderByCreatedAtDesc(Pageable p); long countByStatus(PaymentStatus s); long countByType(PaymentType t); @Query("select coalesce(sum(p.amount),0) from PaymentTransaction p where p.status = com.pvp.travelmatch.entity.PaymentStatus.SUCCESS") long sumSuccessfulAmount(); }
